<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';import interact from 'interactjs';import {useOS} from '../store';import AppContent from './AppContent.vue';
const props=defineProps({win:Object});const os=useOS(),el=ref(null);const app=computed(()=>os.apps.find(a=>a.id===props.win.appId));let interaction;
const style=computed(()=>({left:props.win.x+'px',top:props.win.y+'px',width:props.win.width+'px',height:props.win.height+'px',zIndex:props.win.z}));
function clamp(){const w=props.win;w.width=Math.min(Math.max(340,w.width),innerWidth-16);w.height=Math.min(Math.max(240,w.height),innerHeight-150);w.x=Math.max(8,Math.min(w.x,innerWidth-w.width-8));w.y=Math.max(42,Math.min(w.y,innerHeight-w.height-100))}
onMounted(()=>{interaction=interact(el.value).draggable({allowFrom:'.window-titlebar',ignoreFrom:'button',listeners:{move:e=>{if(props.win.maximized||innerWidth<=640)return;props.win.x+=e.dx;props.win.y+=e.dy;clamp()}}}).resizable({edges:{left:true,right:true,bottom:true},margin:8,listeners:{move:e=>{if(props.win.maximized||innerWidth<=640)return;Object.assign(props.win,{x:props.win.x+e.deltaRect.left,y:props.win.y+e.deltaRect.top,width:e.rect.width,height:e.rect.height});clamp()}}});window.addEventListener('resize',clamp)});
onBeforeUnmount(()=>{interaction?.unset();window.removeEventListener('resize',clamp)});
</script>
<template><section v-if="app" ref="el" v-show="!win.minimized" :class="['os-window',{maximized:win.maximized,active:os.active?.id===win.id}]" :style="style" :data-app="app.id" :aria-label="app.title+' 視窗'" @pointerdown="os.focus(win.id)"><header class="window-titlebar" @dblclick.self="os.toggleMax(win.id)"><div class="traffic"><button class="close" :aria-label="'關閉 '+app.title" @click="os.close(win.id)"><i class="pi pi-times"></i></button><button class="minimize" :aria-label="'最小化 '+app.title" @click="os.minimize(win.id)"><i class="pi pi-minus"></i></button><button class="maximize" :aria-label="'放大 '+app.title" @click="os.toggleMax(win.id)"><i class="pi pi-expand"></i></button></div><span><i :class="['pi',app.icon]"></i> {{app.title}}</span><span class="window-count">{{win.id.toString().padStart(2,'0')}}</span></header><div class="window-body"><AppContent :app="app"/></div></section></template>
